281: void OTAUpdateManager::tick(uint32_t currentMillis) {
282:     if (!_autoCheck || _state != OTAState::Idle) return;
283: 
284:     // Gate: do not attempt any network operation until Wi-Fi is confirmed up.
285:     // This prevents the boot check from racing the TLS/DNS stack during the
286:     // first few seconds after association, and prevents the daily check from
287:     // firing during a temporary network outage.
288:     if (WiFi.status() != WL_CONNECTED) return;
289: 
290:     // --- Boot check: fire once, after Wi-Fi is confirmed connected ---
291:     if (!_hasBootChecked) {
292:         _hasBootChecked = true;
293:         _silentCheck = true;  // Boot checks never show error modals
294:         ESP_LOGI(TAG, "Auto-check: boot trigger (Wi-Fi confirmed connected)");
295:         performUpdate();
296:         return;
297:     }
298: 
299:     // --- Daily scheduled check at _checkHour ---
300:     time_t now = time(nullptr);
301:     if (now < 1000000UL) return; // NTP not yet synced
302: 
303:     struct tm t;
304:     localtime_r(&now, &t);
305:     uint32_t today = static_cast<uint32_t>(now / 86400);
306: 
307:     if (static_cast<uint8_t>(t.tm_hour) == _checkHour && today > _lastCheckDay) {
308:         _lastCheckDay = today;
309:         _silentCheck = true;  // Scheduled checks never show error modals
310:         ESP_LOGI(TAG, "Auto-check: daily trigger at hour %u", (unsigned)_checkHour);
311:         performUpdate();
312:     }
