TEST_F(OtaUpdateManagerTest, Tick_SkipsBootCheck_WhenCheckOnBootFalse) {
    Application app;
    manager.begin(app); // Sets up the task handle
    
    // Disable checkOnBoot via config
    JsonDocument inDoc;
    inDoc["checkOnBoot"] = false;
    manager.applyConfig(inDoc.as<JsonObject>());

    // State should initially be Idle
    EXPECT_EQ(OTAState::Idle, manager.getState());
    
    // Call tick, which acts as the first boot check
    manager.tick(1000);
    
    // It should have skipped performUpdate(), remaining Idle
    EXPECT_EQ(OTAState::Idle, manager.getState());
}

/// tick() performs the boot-time check if checkOnBoot is true (default).
TEST_F(OtaUpdateManagerTest, Tick_PerformsBootCheck_WhenCheckOnBootTrue) {
    Application app;
    manager.begin(app); // Sets up the task handle
    
    // State should initially be Idle
    EXPECT_EQ(OTAState::Idle, manager.getState());
    
    // Call tick, which acts as the first boot check
    manager.tick(1000);
    
    // It should have called performUpdate(), which changes state to Checking
    EXPECT_EQ(OTAState::Checking, manager.getState());
}

